{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("missing required field")

    threshold = case["threshold"]
    calls = case["calls"]
    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    if not math.isfinite(float(threshold)):
        raise ValueError("threshold must be finite")
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    accepted_call_ids = []
    diagnostics = []
    seen_ids = set()
    required = ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable")

    for call in calls:
        if not isinstance(call, dict) or any(field not in call for field in required):
            raise ValueError("invalid call")

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        prediction_tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        if call_id in seen_ids:
            raise ValueError("duplicate call_id")
        seen_ids.add(call_id)
        if isinstance(loss_without, bool) or not isinstance(loss_without, (int, float)):
            raise ValueError("invalid loss_without_call")
        if isinstance(loss_with, bool) or not isinstance(loss_with, (int, float)):
            raise ValueError("invalid loss_with_call")
        if not math.isfinite(float(loss_without)) or not math.isfinite(float(loss_with)):
            raise ValueError("losses must be finite")
        if isinstance(prediction_tokens, bool) or not isinstance(prediction_tokens, int) or prediction_tokens < 0:
            raise ValueError("prediction_tokens must be a nonnegative integer")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be boolean")

        normalized_gain = (float(loss_without) - float(loss_with)) / max(1, prediction_tokens)
        normalized_gain = round(normalized_gain, 6)
        accepted = parseable and normalized_gain >= float(threshold)
        diagnostic = {
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": normalized_gain,
        }
        diagnostics.append(diagnostic)
        if accepted:
            accepted_call_ids.append(call_id)

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
